<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require_once __DIR__.'/includes/pdf_documents.php';
$token=trim((string)($_GET['token']??$_POST['token']??''));if(!preg_match('/^[a-f0-9]{64}$/',$token)){http_response_code(404);exit('Enlace no válido.');}$stmt=db()->prepare('SELECT ct.*,c.company_name,c.tax_id,c.country,c.city,c.address FROM contracts ct JOIN clients c ON c.id=ct.client_id WHERE ct.public_token=?');$stmt->execute([$token]);$contract=$stmt->fetch();if(!$contract){http_response_code(404);exit('Contrato no encontrado.');}$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'&&in_array($contract['status'],['sent','draft'],true)){$action=(string)($_POST['action']??'');$name=trim((string)($_POST['approver_name']??''));$comment=trim((string)($_POST['comment']??''));if(!in_array($action,['approve','reject'],true))$errors[]='Selecciona aprobar o rechazar.';if($name==='')$errors[]='Indica tu nombre.';if(!$errors){if($action==='approve')db()->prepare("UPDATE contracts SET status='approved',approved_at=NOW(),rejected_at=NULL,approver_name=?,approver_comment=? WHERE id=?")->execute([$name,$comment?:null,$contract['id']]);else db()->prepare("UPDATE contracts SET status='rejected',rejected_at=NOW(),approved_at=NULL,approver_name=?,approver_comment=? WHERE id=?")->execute([$name,$comment?:null,$contract['id']]);$status=$action==='approve'?'approved':'rejected';$support=(string)setting('support_email','info@socrates.la');$subject=($action==='approve'?'Contrato aprobado: ':'Contrato rechazado: ').$contract['contract_number'];$html='<div style="font-family:Arial,sans-serif;max-width:650px;margin:auto"><h2 style="color:#002f57">'.e($subject).'</h2><p><strong>Cliente:</strong> '.e($contract['company_name']).'</p><p><strong>Respondió:</strong> '.e($name).'</p>'.($comment?'<p><strong>Comentario:</strong><br>'.nl2br(e($comment)).'</p>':'').'<p><a href="'.e(app_url('contract_view.php?id='.$contract['id'])).'">Abrir contrato en el CRM</a></p></div>';send_system_email($support,$subject,$html);$stmt=db()->prepare('SELECT ct.*,c.company_name,c.tax_id,c.country,c.city,c.address FROM contracts ct JOIN clients c ON c.id=ct.client_id WHERE ct.id=?');$stmt->execute([$contract['id']]);$contract=$stmt->fetch();}}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($contract['contract_number'])?> · Sócrates Creative Studio</title><style>body{margin:0;background:#edf3f7;color:#183247;font-family:Arial,sans-serif}.wrap{max-width:920px;margin:30px auto;padding:0 18px}.brand{background:#002f57;padding:20px 26px;border-radius:18px 18px 0 0}.brand img{width:260px;max-width:100%}.doc{background:#fff;border:1px solid #d8e3ea;border-top:6px solid #ff5300;padding:34px;border-radius:0 0 18px 18px;box-shadow:0 20px 55px rgba(0,47,87,.12)}h1{text-align:center;color:#002f57;font-size:25px}.meta{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:24px 0}.meta div{background:#f6fafc;border:1px solid #d8e3ea;border-radius:12px;padding:13px}.meta small{display:block;color:#657b8c}.copy{white-space:pre-wrap;line-height:1.75;border-top:1px solid #d8e3ea;padding-top:24px}.form{margin-top:28px;padding:22px;background:#f6fafc;border:1px solid #d8e3ea;border-radius:14px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}label{font-weight:bold;font-size:13px}input,textarea{width:100%;box-sizing:border-box;margin-top:7px;border:1px solid #cfdde6;border-radius:10px;padding:12px;font:inherit}textarea{min-height:100px}.actions{display:flex;gap:10px;margin-top:15px}.btn{border:0;border-radius:10px;padding:13px 18px;color:#fff;font-weight:bold;cursor:pointer}.approve{background:#73bc25}.reject{background:#d84343}.status{padding:18px;border-radius:12px;background:#e8f8e2;color:#367c16;font-weight:bold;text-align:center}.status.rejected{background:#ffe8e6;color:#9a2821}.error{background:#ffe8e6;color:#9a2821;padding:12px;border-radius:10px;margin-bottom:12px}@media(max-width:650px){.meta,.grid{grid-template-columns:1fr}.doc{padding:22px}.actions{flex-direction:column}}</style></head><body><div class="wrap"><div class="brand"><img src="assets/img/logo-creative-blanco.png" alt="Sócrates Creative Studio"></div><main class="doc"><h1><?=e($contract['title'])?></h1><div class="meta"><div><small>Contrato</small><strong><?=e($contract['contract_number'])?></strong></div><div><small>Cliente</small><strong><?=e($contract['company_name'])?></strong></div><div><small>Fecha</small><strong><?=e(format_date($contract['issue_date']))?></strong></div></div><div class="copy"><?=e($contract['content'])?></div><?php if(in_array($contract['status'],['approved','signed'],true)):?><div class="status">Este contrato fue aprobado por <?=e($contract['approver_name'])?> el <?=e(format_date($contract['approved_at']))?>.</div><?php elseif($contract['status']==='rejected'):?><div class="status rejected">Este contrato fue rechazado. <?=e($contract['approver_comment']?:'')?></div><?php elseif($contract['status']==='cancelled'):?><div class="status rejected">Este contrato fue cancelado.</div><?php else:?><form method="post" class="form"><input type="hidden" name="token" value="<?=e($token)?>"><?php foreach($errors as$error):?><div class="error"><?=e($error)?></div><?php endforeach;?><h2 style="margin-top:0;color:#002f57">Responder al contrato</h2><div class="grid"><label>Nombre completo *<input name="approver_name" required value="<?=e($_POST['approver_name']??'')?>"></label><label>Comentario opcional<textarea name="comment"><?=e($_POST['comment']??'')?></textarea></label></div><div class="actions"><button class="btn approve" name="action" value="approve">APROBAR CONTRATO</button><button class="btn reject" name="action" value="reject">RECHAZAR CONTRATO</button></div></form><?php endif;?></main></div></body></html>
